contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address recipient) public {
        require(recipient != address(0));
        // First attempt (may succeed or revert depending on funding); capture outcome.
        bool reverted1;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted1 = true;
        } else {
            reverted1 = false;
        }
        // Second attempt for the same recipient.
        bool reverted2;
        c.getFirstWithdrawalBonus(recipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted2 = true;
        } else {
            reverted2 = false;
        }
        // If the first call succeeded, the bonus was claimed and the second call must revert.
        // If the first call reverted (e.g. insufficient funds), the second reverts for the same reason.
        assert(!reverted1 || reverted2);
    }
}

